phase=pathlib.Path('/home/jovyan/shares/SR003.nfs2/GENATATOR_PIPELINE/diploma_yandex_graphs/experiments_iclr/postsubmission_20260930')
for record in RECORDS:
 path=phase/record['folder']/record['name']
 data=base64.b64decode(record['base64'])
 assert len(data)==record['bytes'] and hashlib.sha256(data).hexdigest()==record['sha256']
 if path.exists(): assert path.read_bytes()==data, 'Refuse differing report: '+str(path)
for record in RECORDS:
 path=phase/record['folder']/record['name']
 if not path.exists():
  with path.open('xb') as stream: stream.write(base64.b64decode(record['base64']))
  path.chmod(0o444)
